-- Source-reviewed IPA 2021-06-13 coding, database and network questions.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210613-q23','exam-fe','顧客コードの桁数','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問23・改編】A〜Zの英大文字26種類を使い、顧客ごとに固定桁数のコードを割り当てる。現在8,000人の顧客が毎年2割ずつ増える。3年後に全顧客に重複なく割り当てるために必要な最小桁数は何桁か。','[{"id":"a","text":"3"},{"id":"b","text":"4"},{"id":"c","text":"5"},{"id":"d","text":"6"}]','"a"','3年後は8,000×1.2³=13,824人。26²=676では不足し、26³=17,576で足りるので3桁。 中文：三年后13824人；两位有676种，三位有17576种，因此需要3位。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q24','exam-fe','モーフィング','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問24・改編】コンピュータアニメーション技法であるモーフィングの説明はどれか。','[{"id":"a","text":"画像AからBへ滑らかに変化するよう、中間画像を複数作る"},{"id":"b","text":"実際の身体の動きをデジタルデータとして収集し、動きの画像を作る"},{"id":"c","text":"動く部分を視点から遠い順に背景へ重ねて奥行きのある2次元アニメーションを作る"},{"id":"d","text":"手描きの線画を読み込み、閉領域を同じ色で彩色する"}]','"a"','モーフィングは二つの画像間を滑らかに変形させる中間画像を作る技法。 中文：变形动画通过生成中间图像让两幅图像平滑变化。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q26','exam-fe','トランザクション原子性','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問26・改編】トランザクションの更新処理が完全に実行されるか、全く実行されなかったように取り消されるかのいずれかとなる特性はどれか。','[{"id":"a","text":"一貫性"},{"id":"b","text":"原子性"},{"id":"c","text":"耐久性"},{"id":"d","text":"独立性"}]','"b"','原子性は処理を全実行または全取り消しとする性質。 中文：原子性保证事务要么全部执行，要么全部撤销。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q27','exam-fe','ロールフォワード','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問27・改編】トランザクションTはチェックポイント取得後に完了し、その後システム障害が発生した。チェックポイントとトランザクションログを利用し、Tの更新内容を終了直後の状態に戻す復旧技法はどれか。','[{"id":"a","text":"2相ロック"},{"id":"b","text":"シャドウページ"},{"id":"c","text":"ロールバック"},{"id":"d","text":"ロールフォワード"}]','"d"','完了済みの更新をログから再適用するのはロールフォワード。ロールバックは未完了の更新を取り消す。 中文：利用日志重做已完成的更新是前滚；回滚用于撤销未完成更新。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q28','exam-fe','共有・専有ロック','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問28・改編】トランザクションの同時実行制御に使うロックについて適切な動作はどれか。','[{"id":"a","text":"共有ロック済みの資源に、別トランザクションの共有ロック取得を認める"},{"id":"b","text":"共有ロック済みの資源に、別トランザクションの専有ロック取得を認める"},{"id":"c","text":"専有ロック済みの資源に、別トランザクションの共有ロック取得を認める"},{"id":"d","text":"専有ロック済みの資源に、別トランザクションの専有ロック取得を認める"}]','"a"','共有ロック同士は両立するが、専有ロックは他の共有・専有ロックと両立しない。 中文：共享锁之间兼容；排他锁与其他共享锁或排他锁不兼容。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q29','exam-fe','データウェアハウス','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問29・改編】企業の活動で得た大量のデータを整理・統合して蓄積し、意思決定支援などに利用するものはどれか。','[{"id":"a","text":"データアドミニストレーション"},{"id":"b","text":"データウェアハウス"},{"id":"c","text":"データディクショナリ"},{"id":"d","text":"データマッピング"}]','"b"','データウェアハウスは分析・意思決定のために統合データを蓄積する。 中文：数据仓库整合并保存数据，供分析和决策使用。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q30','exam-fe','データ転送時間','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問30・改編】10Mバイトのデータを100,000ビット/秒の回線で送る。伝送効率は50%、1Mバイトは10⁶バイトとする。転送時間は何秒か。','[{"id":"a","text":"200"},{"id":"b","text":"400"},{"id":"c","text":"800"},{"id":"d","text":"1,600"}]','"d"','10×10⁶バイト=80×10⁶ビット。実効速度は100,000×0.5=50,000ビット/秒なので1,600秒。 中文：数据共8000万比特，实际速度每秒5万比特，需1600秒。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption');
